import json

# Two-adjacent-diagonals pattern
alt_diag = []
for i in range(8):
    row = [4] * 8
    for j in range(8):
        if i == j:
            row[j] = 0
        elif i + 1 == j:
            row[j] = 0
    alt_diag.append(row)

print("Two-diagonal band:")
for row in alt_diag:
    print(row)

print("\nSubmitting:")
print(json.dumps({"action": "submit", "grid": alt_diag}))

import json

# Center diamond pattern (rhombus) - 0s form a diamond in the center
diamond = [[4] * 8 for _ in range(8)]
for i in range(8):
    for j in range(8):
        distance_from_center = (abs(i - 3.5) + abs(j - 3.5))
        if distance_from_center <= 3 or distance_from_center >= 8 - 3:  # Inside diamond
            # Map to a smaller Manhattan distance threshold
            dist = abs(i - 3) + abs(j - 3)
            if dist <= 2:
                diamond[i][j] = 0

print("Manhattan diamond:")
for row in diamond:
    print(row)

# Let me try a simpler diamond
diamond2 = [[4] * 8 for _ in range(8)]
for i in range(8):
    for j in range(8):
        if abs(i - 3) + abs(j - 3) <= 2:
            diamond2[i][j] = 0

print("\nSimpler diamond:")
for row in diamond2:
    print(row)

print("\nSubmitting diamond:")
print(json.dumps({"action": "submit", "grid": diamond2}))
